WITH filtered_stores AS (SELECT * FROM stores WHERE region IN ('West', 'Central') AND (city = 'Bangkok' OR city NOT IN ('Tokyo', 'Bangkok', 'New York'))), Agg AS (SELECT CASE WHEN region IN ('South', 'West') THEN 'group_a' ELSE 'other' END AS region_group, ROUND((100 * SUM(CASE WHEN region = 'West' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_west, SUM(CASE WHEN region = 'West' THEN sqft ELSE 0 END) AS west_sqft FROM filtered_stores GROUP BY CASE WHEN region IN ('South', 'West') THEN 'group_a' ELSE 'other' END) SELECT region_group, pct_west, west_sqft FROM Agg WHERE west_sqft < 53;
